    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

// Function to compute the sum of exponents of prime p in the factorization of 1! * 2! * ... * n!
// This is equivalent to sum_{k=1}^{n} v_p(k!) where v_p(k!) is the exponent of p in k!
// v_p(k!) = floor(k/p) + floor(k/p^2) + floor(k/p^3) + ...
// So we need sum_{k=1}^{n} [floor(k/p) + floor(k/p^2) + ...]
// = sum_{j=1}^{infty} sum_{k=1}^{n} floor(k/p^j)
// For a fixed j, let m = p^j. sum_{k=1}^{n} floor(k/m) = sum_{i=1}^{floor(n/m)} i * m + ... 
// Actually, sum_{k=1}^{n} floor(k/m) = m * sum_{i=1}^{floor(n/m)-1} i + (n - m*floor(n/m) + 1) * floor(n/m)
// Wait, let's think again.
// sum_{k=1}^{n} floor(k/m) = sum_{i=1}^{floor(n/m)} (number of k such that floor(k/m) >= i)
// = sum_{i=1}^{floor(n/m)} (n - i*m + 1)
// Let q = floor(n/m). Then sum = sum_{i=1}^{q} (n + 1 - i*m) = q*(n+1) - m*q*(q+1)/2

long long sum_floor_div(long long n, long long m) {
    // Compute sum_{k=1}^{n} floor(k/m)
    if (m > n) return 0;
    long long q = n / m;
    // sum = q*(n+1) - m*q*(q+1)/2
    // We need to compute this modulo MOD, but the values can be huge.
    // n up to 1e18, m up to 1e9, q up to 1e18/m
    // q*(n+1) can be up to 1e36, which doesn't fit in long long.
    // We need to compute this modulo MOD carefully.

    // Let's compute each term modulo MOD.
    // But division by 2 needs modular inverse.

    // Actually, let's compute the exact value if possible, or use modular arithmetic.
    // Since n <= 1e18 and m >= 2, q <= 5e17.
    // q*(n+1) <= 5e17 * 1e18 = 5e35, which is too big for long long (max ~9e18).

    // We need to compute (q*(n+1) - m*q*(q+1)/2) mod MOD.
    // Let's compute each part mod MOD.

    long long q_mod = q % MOD;
    long long n1_mod = (n + 1) % MOD;
    long long m_mod = m % MOD;

    // term1 = q * (n+1) mod MOD
    long long term1 = (q_mod * n1_mod) % MOD;

    // term2 = m * q * (q+1) / 2 mod MOD
    // We need to divide by 2. Since MOD is prime, we can use modular inverse of 2.
    // But q*(q+1) is always even, so we can divide one of them by 2 before multiplying.

    long long q_plus_1 = q + 1;
    long long q_plus_1_mod = q_plus_1 % MOD;

    // To compute m * q * (q+1) / 2 mod MOD:
    // If q is even, compute (q/2) * (q+1) * m mod MOD
    // If q+1 is even, compute q * ((q+1)/2) * m mod MOD

    long long term2;
    if (q % 2 == 0) {
        long long q_half = q / 2;
        long long q_half_mod = q_half % MOD;
        term2 = (m_mod * q_half_mod) % MOD;
        term2 = (term2 * q_plus_1_mod) % MOD;
    } else {
        long long qp1_half = (q + 1) / 2;
        long long qp1_half_mod = qp1_half % MOD;
        term2 = (m_mod * q_mod) % MOD;
        term2 = (term2 * qp1_half_mod) % MOD;
    }

    long long result = (term1 - term2 + MOD) % MOD;
    return result;
}

// Function to compute the total exponent of prime p in the product f(x,1)*...*f(x,n)
// This is sum_{k=1}^{n} v_p(k!) = sum_{j=1}^{infty} sum_{k=1}^{n} floor(k/p^j)
long long total_exponent(long long p, long long n) {
    long long total = 0;
    long long power = p;
    while (power <= n) {
        total = (total + sum_floor_div(n, power)) % MOD;
        // Check for overflow: if power > n/p, then next power would exceed n
        if (power > n / p) break;
        power *= p;
    }
    return total;
}

