    for (long long i = 2; i * i <= x; i++) {
        if (x % i == 0) {
            factors.push_back(i);
            while (x % i == 0) {
                x /= i;
            }
        }
    }
    if (x > 1) {
        factors.push_back(x);
    }
    return factors;
}

int main() {
    long long x, n;
    cin >> x >> n;

    vector<long long> primes = prime_factors(x);

    long long answer = 1;

    for (long long p : primes) {
        long long exp = total_exponent(p, n);
        answer = (answer * mod_pow(p, exp, MOD)) % MOD;
    }

